	String KEY_UNLOCKED_ITEMS = "unlockedItems";

	@ConfigItem(
		keyName = KEY_UNLOCKED_ITEMS,
		name = "Unlocked Items",
		description = "Stores all unlocked items as a CSV"
	)
	default String unlockedItems()
