	private final int widgetId;
	private final RuneType[] requiredRunes;

	private static final Map<Integer, Spell> BY_WIDGET_ID = new HashMap<>();
	private static final Map<String, Spell> BY_CLEAN_NAME = new HashMap<>();

	private static final String[] PREFIXES_TO_STRIP = {
		"defensiveautocast",
		"defensivecast",
		"autocast",
		"defensive",
		"choose",
		"select",
		"cast"
	};

	static
	{
		for (Spell spell : values())
		{
			BY_WIDGET_ID.put(spell.widgetId, spell);
			BY_CLEAN_NAME.put(cleanName(spell.name()), spell);
		}
		// Aliases
		BY_CLEAN_NAME.put("slayersdart", MAGIC_DART);
		BY_CLEAN_NAME.put("slayerdart", MAGIC_DART);
		BY_CLEAN_NAME.put("ibansblast", IBAN_BLAST);
		BY_CLEAN_NAME.put("crumbleundead", CRUMBLE_UNDEAD);
	}

	Spell(int widgetId, RuneType... requiredRunes)
	{
		this.widgetId = widgetId;
		this.requiredRunes = requiredRunes;
	}

	public int getWidgetId()
	{
		return widgetId;
	}

	public RuneType[] getRequiredRunes()
	{
		return requiredRunes;
	}

	public static Spell forWidgetId(int widgetId)
	{
		return BY_WIDGET_ID.get(widgetId);
	}

	public static String cleanName(String name)
	{
		if (name == null)
		{
			return "";
		}
		return Text.removeTags(name)
			.toLowerCase()
			.replaceAll("[^a-z0-9]", "");
	}

	public static Spell forCleanName(String name)
	{
		if (name == null)
		{
			return null;
		}
		String clean = cleanName(name);
		if (clean.isEmpty())
		{
			return null;
		}
		Spell spell = BY_CLEAN_NAME.get(clean);
		if (spell != null)
		{
			return spell;
		}
		for (String prefix : PREFIXES_TO_STRIP)
		{
			if (clean.startsWith(prefix) && clean.length() > prefix.length())
			{
				Spell match = BY_CLEAN_NAME.get(clean.substring(prefix.length()));
				if (match != null)
				{
					return match;
				}
			}
		}
		return null;
	}
}

package com.itemlocker;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class SpellLockerOverlay extends AbstractSpellOverlay
{
	@Inject
	public SpellLockerOverlay(Client client, ItemLockerPlugin plugin)
	{
		super(client, plugin);
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.MANUAL);
		drawAfterInterface(InterfaceID.MAGIC_SPELLBOOK);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Widget tooltip = client.getWidget(InterfaceID.MagicSpellbook.TOOLTIP);
		Rectangle tooltipBounds = findTooltipBoundsFromWidget(tooltip);
		Shape originalClip = graphics.getClip();

		try
		{
			applyTooltipClip(graphics, tooltipBounds, originalClip);

			for (Spell spell : Spell.values())
			{
				Widget widget = client.getWidget(spell.getWidgetId());
				if (widget == null || widget.isHidden())
				{
					continue;
				}

				if (!plugin.isSpellCastable(spell))
				{
					Rectangle bounds = widget.getBounds();
					renderLockedOverlay(graphics, bounds);
				}
			}
		}
		finally
		{
			graphics.setClip(originalClip);
		}

		return null;
	}
}

